def clean(df):
    df = df.copy()
    # Normalize Category (strip extra spaces)
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    # Fix Price text numbers like "$300.00"
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # Ensure numeric Quantity/Revenue
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    if 'Revenue' in df.columns:
        df['Revenue'] = pd.to_numeric(df['Revenue'], errors='coerce')
    # Validate Date format YYYY-MM-DD
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    # Remove exact duplicate rows
    df = df.drop_duplicates()
    # Enforce unique Order_ID (keep first)
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    # Filter out-of-range / negative values per rules
    if 'Quantity' in df.columns:
        df = df[df['Quantity'] >= 1]
    if 'Price' in df.columns:
        df = df[df['Price'] >= 0]
    # Cross-column: Revenue = Quantity * Price (recompute to fix)
    if all(c in df.columns for c in ['Quantity','Price','Revenue']):
        df['Revenue'] = df['Quantity'] * df['Price']
    # Drop missing Category keys and filter allowed categories
    if 'Category' in df.columns:
        df = df.dropna(subset=['Category'])
        df = df[df['Category'].astype(str).str.strip() != '']
        df = df[df['Category'].str.lower() != 'nan']
        allowed = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
        df = df[df['Category'].isin(allowed)]
    return df

def answer(df):
    # df is expected to be cleaned
    if 'Category' not in df.columns:
        return {}
    df = df.dropna(subset=['Category'])
    df = df[df['Category'].astype(str).str.strip() != '']
    counts = df.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
